const Fs=require("fs"),Path=require("path"),MD5=require("./MD5"),FileUtil={copy(i,e){if(Fs.existsSync(i)){var s=Fs.statSync(i);if(s.isDirectory()){Fs.existsSync(e)||Fs.mkdirSync(e);for(const t of Fs.readdirSync(i))this.copy(Path.join(i,t),Path.join(e,t))}else s.isFile()&&Fs.writeFileSync(e,Fs.readFileSync(i))}},delete(i){if(Fs.existsSync(i)){var e=Fs.statSync(i);if(e.isDirectory()){for(const s of Fs.readdirSync(i))this.delete(Path.join(i,s));Fs.rmdirSync(i)}else e.isFile()&&Fs.unlinkSync(i)}},map(i,e){if(Fs.existsSync(i)){var s=Fs.statSync(i);if(s.isDirectory())for(const t of Fs.readdirSync(i))this.map(Path.join(i,t),e);else s.isFile()&&e(i,s)}},getFileStr(i){return Fs.readFileSync(i).toString()},getFileMd5(i){i=Fs.readFileSync(i).toString();return MD5.md5(i)}};module.exports=FileUtil;